import { Link } from "react-router-dom";
import { useEffect, useState } from "react";

function Navbar() {
  const [userId, setUserId] = useState(localStorage.getItem("userId"));

  // Listen to storage changes across tabs
  useEffect(() => {
    const handleStorage = () => {
      setUserId(localStorage.getItem("userId"));
    };

    window.addEventListener("storage", handleStorage);
    return () => {
      window.removeEventListener("storage", handleStorage);
    };
  }, []);

  const handleLogout = () => {
    localStorage.removeItem("userId");
    localStorage.removeItem("full_name");
    setUserId(null); // force re-render
    window.location.href = "/login";
  };

  return (
    <nav className="bg-black bg-opacity-80 flex justify-end items-center h-12 px-8 shadow-lg">
      <Link
        to="/"
        className="text-white mx-4 text-lg uppercase hover:text-blue-400"
      >
        Back to First Page
      </Link>
      {userId ? (
        <>
          <Link
            to="/homes"
            className="text-white mx-4 text-lg uppercase hover:text-blue-400"
          >
            Homes
          </Link>
          <Link
            to="/upload"
            className="text-white mx-4 text-lg uppercase hover:text-blue-400"
          >
            Upload
          </Link>
          <Link
            to={`/dashboard/${userId}`}
            className="text-white mx-4 text-lg uppercase hover:text-blue-400"
          >
            Dashboard
          </Link>
          <button
            onClick={handleLogout}
            className="text-white mx-4 text-lg uppercase hover:text-blue-400"
          >
            Logout
          </button>
        </>
      ) : (
        <>
          <Link
            to="/login"
            className="text-white mx-4 text-lg uppercase hover:text-blue-400"
          >
            Login
          </Link>
          <Link
            to="/signup"
            className="text-white mx-4 text-lg uppercase hover:text-blue-400"
          >
            Signup
          </Link>
        </>
      )}
    </nav>
  );
}

export default Navbar;
